using System.Globalization;
using System.Reflection;
using System.Text;
using System.Xml.Linq;

namespace Latiprimere.ApiReference;

/// <summary>
/// Writes a type's page: its declaration and documentation, then each member's, grouped by kind.
/// </summary>
internal sealed class TypePageWriter
{
	/// <summary>The comment at the top of every generated page.</summary>
	internal const string GeneratedNotice =
		"<!-- Generated by tools/api-reference from the XML documentation comments in src/. Don't edit this page: edit the comments, then run `dotnet run --project tools/api-reference`. -->";

	private readonly XmlDocumentation documentation; // The packages' XML documentation
	private readonly DocMarkdown markdown;           // Turns documentation into Markdown
	private readonly ReferenceLinks links;           // Links to types
	private readonly Signatures signatures = new Signatures(); // Writes declarations

	/// <summary>
	/// Initialises a new instance of the <see cref="TypePageWriter"/> class.
	/// </summary>
	/// <param name="documentation">The packages' XML documentation.</param>
	/// <param name="markdown">Turns documentation into Markdown.</param>
	/// <param name="links">Links to types.</param>
	public TypePageWriter(XmlDocumentation documentation, DocMarkdown markdown, ReferenceLinks links)
	{
		ArgumentNullException.ThrowIfNull(documentation);
		ArgumentNullException.ThrowIfNull(markdown);
		ArgumentNullException.ThrowIfNull(links);

		this.documentation = documentation;
		this.markdown = markdown;
		this.links = links;
	}

	/// <summary>
	/// Writes the front matter that begins every page: its title and description, and no "Edit page" link, since the
	/// page is generated.
	/// </summary>
	/// <param name="output">Where to write.</param>
	/// <param name="title">The page's title.</param>
	/// <param name="description">Its description, in plain text.</param>
	public static void WriteFrontMatter(StringBuilder output, string title, string description)
	{
		ArgumentNullException.ThrowIfNull(output);

		output.Append("---\n");
		output.Append("title: ").Append(TypePageWriter.YamlString(title)).Append('\n');

		if (description.Length > 0)
		{
			output.Append("description: ").Append(TypePageWriter.YamlString(description)).Append('\n');
		}

		// The website links each page to its source to edit; a generated page is changed through the comments instead
		output.Append("editUrl: false\n");
		output.Append("---\n\n");
		output.Append(TypePageWriter.GeneratedNotice).Append("\n\n");
	}

	/// <summary>
	/// Writes a type's page.
	/// </summary>
	/// <param name="page">The page.</param>
	/// <returns>The page's Markdown.</returns>
	public string Write(TypePage page)
	{
		ArgumentNullException.ThrowIfNull(page);

		Type type = page.Type;
		XElement? documentation = this.documentation.ForType(type);
		StringBuilder output = new StringBuilder();

		TypePageWriter.WriteFrontMatter(output, type.Name, this.markdown.ToPlainText(documentation?.Element("summary")));

		string kind = Signatures.Kind(type);
		string kindName = char.ToUpperInvariant(kind[0]) + kind[1..];

		output.Append(CultureInfo.InvariantCulture, $"**{kindName}** in the `{type.Namespace}` namespace, from the [{page.Package.Name}](/docs/reference/#{page.Package.Anchor}) package.");
		output.Append(this.Relations(type)).Append("\n\n");

		TypePageWriter.AppendCode(output, Signatures.DeclareType(type));
		TypePageWriter.AppendBlock(output, this.markdown.ToMarkdown(documentation?.Element("summary")));
		TypePageWriter.AppendBlock(output, this.markdown.ToMarkdown(documentation?.Element("remarks")));

		if (type.IsEnum)
		{
			this.WriteEnumValues(output, page);
		}
		else
		{
			this.WriteSection<ConstructorInfo>(output, page, "Constructors");
			this.WriteSection<PropertyInfo>(output, page, "Properties");
			this.WriteSection<MethodInfo>(output, page, "Methods");
			this.WriteSection<FieldInfo>(output, page, "Fields");
			this.WriteSection<EventInfo>(output, page, "Events");
		}

		return output.ToString().TrimEnd('\n') + "\n";
	}

	/// <summary>
	/// Writes a string for YAML front matter, quoted.
	/// </summary>
	/// <param name="text">The string.</param>
	/// <returns>The YAML.</returns>
	private static string YamlString(string text)
	{
		return "\"" + text.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal) + "\"";
	}

	/// <summary>
	/// Adds a block of Markdown, then a blank line, unless it is empty.
	/// </summary>
	/// <param name="output">Where to write.</param>
	/// <param name="block">The Markdown.</param>
	private static void AppendBlock(StringBuilder output, string block)
	{
		if (block.Length > 0)
		{
			output.Append(block).Append("\n\n");
		}
	}

	/// <summary>
	/// Adds a C# code block.
	/// </summary>
	/// <param name="output">Where to write.</param>
	/// <param name="code">The code.</param>
	private static void AppendCode(StringBuilder output, string code)
	{
		output.Append("```csharp\n").Append(code).Append("\n```\n\n");
	}

	/// <summary>
	/// Indents a list item's later lines under it.
	/// </summary>
	/// <param name="markdown">The item's Markdown.</param>
	/// <returns>The Markdown, indented.</returns>
	private static string IndentItem(string markdown)
	{
		return markdown.Replace("\n", "\n  ", StringComparison.Ordinal).Replace("\n  \n", "\n\n", StringComparison.Ordinal);
	}

	/// <summary>
	/// Describes what a type inherits from and implements, with links, as a sentence after the first.
	/// </summary>
	/// <param name="type">The type.</param>
	/// <returns>The sentences, each starting with a space; or nothing.</returns>
	private string Relations(Type type)
	{
		StringBuilder relations = new StringBuilder();

		if (!type.IsValueType && !type.IsInterface && type.BaseType is not null && type.BaseType != typeof(object))
		{
			relations.Append(" Inherits from ").Append(this.links.ToMarkdown(type.BaseType)).Append('.');
		}

		List<Type> interfaces = Signatures.DirectInterfaces(type).ToList();

		if (interfaces.Count > 0)
		{
			string verb = type.IsInterface ? "Extends" : "Implements";

			relations.Append(' ').Append(verb).Append(' ').Append(string.Join(", ", interfaces.Select(this.links.ToMarkdown))).Append('.');
		}

		return relations.ToString();
	}

	/// <summary>
	/// Writes an enum's values, with their numbers and documentation.
	/// </summary>
	/// <param name="output">Where to write.</param>
	/// <param name="page">The enum's page.</param>
	private void WriteEnumValues(StringBuilder output, TypePage page)
	{
		List<FieldInfo> values = page.Members.OfType<FieldInfo>().OrderBy(field => Convert.ToInt64(field.GetRawConstantValue(), CultureInfo.InvariantCulture)).ToList();

		if (values.Count == 0)
		{
			return;
		}

		output.Append("## Values\n\n");

		foreach (FieldInfo value in values)
		{
			XElement? documentation = this.documentation.ForMember(value);
			string number = Convert.ToString(value.GetRawConstantValue(), CultureInfo.InvariantCulture) ?? string.Empty;
			string text = string.Join("\n\n", new[] { documentation?.Element("summary"), documentation?.Element("remarks") }
				.Select(this.markdown.ToMarkdown)
				.Where(block => block.Length > 0));

			output.Append(CultureInfo.InvariantCulture, $"- **`{value.Name}`** (`{number}`)");
			output.Append(text.Length > 0 ? ": " + TypePageWriter.IndentItem(text) : string.Empty).Append('\n');
		}

		output.Append('\n');
	}

	/// <summary>
	/// Writes the section for one kind of member, under a heading for each name, with each overload.
	/// </summary>
	/// <typeparam name="TMember">The kind of member.</typeparam>
	/// <param name="output">Where to write.</param>
	/// <param name="page">The type's page.</param>
	/// <param name="heading">The section's heading.</param>
	private void WriteSection<TMember>(StringBuilder output, TypePage page, string heading)
		where TMember : MemberInfo
	{
		List<TMember> members = page.Members.OfType<TMember>().ToList();

		if (members.Count == 0)
		{
			return;
		}

		output.Append("## ").Append(heading).Append("\n\n");

		foreach (IGrouping<string, TMember> named in members.GroupBy(member => member.Name, StringComparer.Ordinal))
		{
			// Constructors share the section's heading, which their links point to
			if (typeof(TMember) != typeof(ConstructorInfo))
			{
				output.Append("### ").Append(named.Key).Append("\n\n");
			}

			foreach (TMember member in named)
			{
				this.WriteMember(output, member);
			}
		}
	}

	/// <summary>
	/// Writes one member: its declaration, documentation, parameters, return value and exceptions.
	/// </summary>
	/// <param name="output">Where to write.</param>
	/// <param name="member">The member.</param>
	private void WriteMember(StringBuilder output, MemberInfo member)
	{
		XElement? documentation = this.documentation.ForMember(member);

		TypePageWriter.AppendCode(output, this.signatures.Declare(member));
		TypePageWriter.AppendBlock(output, this.markdown.ToMarkdown(documentation?.Element("summary")));
		TypePageWriter.AppendBlock(output, this.markdown.ToMarkdown(documentation?.Element("remarks")));

		if (documentation is null)
		{
			return;
		}

		this.WriteNamedList(output, "Type parameters", documentation.Elements("typeparam"));

		if (member is MethodBase method)
		{
			IEnumerable<XElement> parameters = method.GetParameters()
				.Select(parameter => documentation.Elements("param").FirstOrDefault(element => (string?)element.Attribute("name") == parameter.Name)
									 ?? new XElement("param", new XAttribute("name", parameter.Name ?? string.Empty)));

			this.WriteNamedList(output, "Parameters", parameters);
		}

		string value = this.markdown.ToMarkdown(documentation.Element("value"));
		string returns = this.markdown.ToMarkdown(documentation.Element("returns"));

		if (value.Length > 0)
		{
			output.Append("**Value**\n\n");
			TypePageWriter.AppendBlock(output, value);
		}

		if (returns.Length > 0 && member is MethodInfo { ReturnType: Type returnType } && returnType != typeof(void))
		{
			output.Append("**Returns**\n\n");
			TypePageWriter.AppendBlock(output, returns);
		}

		List<XElement> exceptions = documentation.Elements("exception").ToList();

		if (exceptions.Count > 0)
		{
			output.Append("**Exceptions**\n\n");

			foreach (XElement exception in exceptions)
			{
				string cref = (string?)exception.Attribute("cref") ?? string.Empty;
				string description = this.markdown.ToMarkdown(exception);

				output.Append("- ").Append(this.links.ToMarkdown(cref, null));
				output.Append(description.Length > 0 ? ": " + TypePageWriter.IndentItem(description) : string.Empty).Append('\n');
			}

			output.Append('\n');
		}
	}

	/// <summary>
	/// Writes a list of named items, such as parameters, under a bold heading, unless there are none.
	/// </summary>
	/// <param name="output">Where to write.</param>
	/// <param name="heading">The heading.</param>
	/// <param name="items">The elements, each with a <c>name</c> attribute.</param>
	private void WriteNamedList(StringBuilder output, string heading, IEnumerable<XElement> items)
	{
		List<XElement> list = items.ToList();

		if (list.Count == 0)
		{
			return;
		}

		output.Append("**").Append(heading).Append("**\n\n");

		foreach (XElement item in list)
		{
			string description = this.markdown.ToMarkdown(item);

			output.Append("- `").Append((string?)item.Attribute("name")).Append('`');
			output.Append(description.Length > 0 ? ": " + TypePageWriter.IndentItem(description) : string.Empty).Append('\n');
		}

		output.Append('\n');
	}
}
